using System;
using System.Net;
using System.Net.Sockets;
using System.Threading;

string host = "status.example.test";
int servicePort = 8080;
using var deadline = new CancellationTokenSource(TimeSpan.FromSeconds(3));
IPAddress[] candidates;
try
{
    candidates = await Dns.GetHostAddressesAsync(host, deadline.Token);
}
catch (OperationCanceledException) when (deadline.IsCancellationRequested)
{
    Console.WriteLine("stage=dns-canceled reason=deadline");
    return;
}
catch (SocketException e)
{
    Console.WriteLine($"stage=dns-failed error={e.SocketErrorCode}");
    return;
}

IPAddress? selected = Array.Find(candidates, a => a.AddressFamily == AddressFamily.InterNetwork)
    ?? Array.Find(candidates, a => a.AddressFamily == AddressFamily.InterNetworkV6);
if (selected is null) throw new InvalidOperationException("No IPv4 or IPv6 address was returned");

var remote = new IPEndPoint(selected, servicePort);
using var client = new Socket(remote.AddressFamily, SocketType.Stream, ProtocolType.Tcp);
Console.WriteLine($"stage=connect host={host} candidates={string.Join(",", candidates)} target={remote}");
try
{
    await client.ConnectAsync(remote, deadline.Token);
    Console.WriteLine($"stage=connected local={client.LocalEndPoint} remote={client.RemoteEndPoint}");
}
catch (OperationCanceledException)
{
    Console.WriteLine($"stage=connect-canceled target={remote} reason=deadline");
}
catch (SocketException e)
{
    Console.WriteLine($"stage=connect-failed target={remote} family={remote.AddressFamily} error={e.SocketErrorCode}");
}

using System.Net;
using System.Net.Sockets;
using System.Threading;

var bindEndpoint = new IPEndPoint(IPAddress.Any, 8080);
using var listener = new Socket(bindEndpoint.AddressFamily, SocketType.Stream, ProtocolType.Tcp);
listener.Bind(bindEndpoint);
listener.Listen(backlog: 128);

using Socket accepted = await listener.AcceptAsync(CancellationToken.None);
Console.WriteLine($"local={accepted.LocalEndPoint} remote={accepted.RemoteEndPoint}");
// Local-only test alternative: new IPEndPoint(IPAddress.Loopback, 8080).
// To listen on one specific local IP, use that address here.
